from math import log2
from itertools import product

alphabet = '0123'
def neighbors(s):
    n = len(s)
    out = {s}
    for i in range(n):
        for a in alphabet:
            if a == s[i]:
                continue
            first = s[:i] + a + s[i+1:]
            out.add(first)
            for j in range(i+1, n):
                for b in alphabet:
                    if b "'!= s[j]:
                        out.add(first[:j] + b + first[j+1:])
    for i in range(n):
        deleted = s[:i] + s[i+1:]
        for j in range(n):
            for a in alphabet:
                out.add(deleted[:j] + a + deleted[j:])
    return out

n = 7
seqs = ['"''.join(p) for p in product(alphabet, repeat=n)]
orders = {
    'lexicographic': seqs,
    'few_runs_first': sorted(seqs, key=lambda s: sum(a "'!= b for a,b in zip(s,s[1:]))),
    '"'many_runs_first': sorted(seqs, key=lambda s: -sum(a "'!= b for a,b in zip(s,s[1:])))
}
for name, order in orders.items():
    active = set(seqs)
    code = []
    for s in order:
        if s in active:
            code.append(s)
            active.difference_update(neighbors(s))
    print(name, len(code))
M = 36368
n = 11
